const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const OUTPUT_DIR = path.join(__dirname, '..', 'engine', 'data', 'weaponry');

if (!fs.existsSync(OUTPUT_DIR)) {
  fs.mkdirSync(OUTPUT_DIR, { recursive: true });
}

const existingFiles = new Set(fs.readdirSync(OUTPUT_DIR));

function slugify(str) {
  return str
    .toLowerCase()
    .replace(/['']/g, '')
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_|_$/g, '')
    .slice(0, 80);
}

function genId() {
  return crypto.randomBytes(16).toString('hex');
}

function writeEntity(entity) {
  const truncName = entity.name.slice(0, 60);
  const filename = slugify(truncName) + '.json';
  if (existingFiles.has(filename)) {
    console.log(`SKIP (exists): ${filename}`);
    return false;
  }
  const filepath = path.join(OUTPUT_DIR, filename);
  fs.writeFileSync(filepath, JSON.stringify(entity, null, 2), 'utf-8');
  existingFiles.add(filename);
  console.log(`WROTE: ${filename}`);
  return true;
}

