const allWeapons = [...pistols, ...revolvers, ...shotguns];
let written = 0;
let skipped = 0;

for (const w of allWeapons) {
  const entity = {
    id: genId(),
    name: w.name,
    type: "weapon",
    aliases: w.aliases,
    category: w.category,
    description: w.description,
    manufacturer: w.manufacturer,
    tier_availability: w.tier_availability,
    legality: w.legality,
    base_technologies: w.base_technologies,
    specifications: w.specifications,
    tactical_use: w.tactical_use,
    cultural_context: w.cultural_context,
    known_users: w.known_users,
    story_hooks: w.story_hooks,
    ammunition_type: w.ammunition_type,
    tags: w.tags
  };

  if (writeEntity(entity)) {
    written++;
  } else {
    skipped++;
  }
}

console.log(`\nDone. Wrote ${written}, skipped ${skipped}. Total in directory: ${fs.readdirSync(OUTPUT_DIR).length}`);
